insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 1, 'On the Ekene Deep deal (synthetic), FIN pays 40.000000 percent of the well to earn a 30.000000 percent participating interest, and the chance of success is 25.000000 percent. What is FIN''s EVPI?', '["6745331.458602, the value the stated two-signal seismic survey adds to FIN''s position before its cost", "19585775.278136, the value perfect foresight adds to EKO''s position as farmor on the same prospect", "14393775.278136, the chance of success times its farm in success payoff of 57575101.112542", "17987550.556271, the EMV of farming in once a bright amplitude signal has been read by FIN"]'::jsonb, 2, 'FIN declines without information (EMV 0.000000). Knowing the outcome, it farms in on a success and declines on a dry hole, so its EMV with perfect information is 25.000000 percent of 57575101.112542: 14393775.278136, and EVPI is that less 0.000000. 6745331.458602 is the EVII of the real survey; 19585775.278136 is EKO''s EVPI; 17987550.556271 is FIN''s EMV after a bright signal.'),
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 2, 'With perfect information, what is EKO''s EMV as farmor on the Ekene Deep prospect at a 25.000000 percent chance of success?', '["39418808.982316: drill alone on a known success, walk away from a known dry hole", "26725365.162782: the chance-weighted EMV of its best action after each of the two amplitude signals", "19833033.704181: its EMV after the farm-out on the stated terms, the best action without any survey", "64837617.964633: the EMV of drilling alone once the survey has come back with a bright amplitude"]'::jsonb, 0, 'With perfect information EKO drills alone on a known success, where its 70.000000 percent pays 157675235.929265, and walks away on a known dry hole, worth 0.000000; 25.000000 percent of 157675235.929265 is 39418808.982316 (engine). 26725365.162782 is the EMV with the imperfect survey; 19833033.704181 is the EMV without information; 64837617.964633 is the EMV after a bright signal alone.'),
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 3, 'The Ekene survey states likelihoods of 75.000000 percent given success and 25.000000 percent given a dry hole for the bright amplitude signal. At a 25.000000 percent chance of success, what chance of that signal does the engine return?', '["0.750000", "0.625000", "0.500000", "0.375000"]'::jsonb, 3, 'The chance of a bright signal is the chance of success times 75.000000 percent plus the chance of a dry hole times 25.000000 percent, and the engine returns 0.375000, consistent by construction with Bayes. 0.750000 confuses the likelihood given success with the chance of the signal; 0.625000 is the dim signal''s chance; 0.500000 restates the posterior chance of success after bright as if it were the signal''s chance.'),
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 4, 'Once the survey reads dim, what posterior does informationValue print for a discovery at Ekene Deep?', '["25.000000 percent, the prior chance left unmoved by any signal", "10.000000 percent, down from the stated 25.000000", "50.000000 percent, the posterior after bright", "27.281304 percent, FIN''s break-even chance"]'::jsonb, 1, 'The engine returns 10.000000 percent after a dim signal and 50.000000 after a bright one; the likelihoods move the chance of success in opposite directions. 25.000000 is the prior, which only an uninformative signal leaves unmoved; 27.281304 is FIN''s break-even chance, a different figure of a named position.'),
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 5, 'Why does a bright amplitude signal turn FIN from declining to farming in on the Ekene Deep terms?', '["It lowers the share of the well FIN must pay, so the promote on the deal shrinks toward the break-even promote", "It lifts the chance of success to 50.000000 percent, above FIN''s break-even chance of 27.281304", "It raises the success-case value at 100 percent, so FIN''s success payoff grows", "It removes the dry-hole outcome, so farming in can lose FIN nothing at all"]'::jsonb, 1, 'The signal changes only the chance of success the side acts on. FIN''s EMV for farming in is negative below its break-even chance of 27.281304 percent and positive above it; the stated 25.000000 sits below, and a bright signal moves it to 50.000000. The deal terms, the promote and the success-case value do not move, and a bright signal still leaves a 50.000000 percent chance of a dry hole.'),
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 6, 'How does the engine reach FIN''s EMV with the Ekene survey, 6745331.458602?', '["0.500000 x 57575101.112542 plus 0.500000 x -21600000.000000, the farm in payoffs at the two posteriors averaged", "57575101.112542 x 25.000000 percent, less the survey''s stated cost of 1500000.000000 taken off at the end", "14393775.278136 less 1500000.000000, the EVPI of FIN reduced by the stated cost of the seismic survey", "0.375000 x 17987550.556271 for farming in after bright, plus 0.625000 x 0.000000 for declining after dim"]'::jsonb, 3, 'The engine weights each signal''s best EMV by the chance of that signal: 0.375000 x 17987550.556271 + 0.625000 x 0.000000 = 6745331.458602 (engine), and EVII is that less the EMV without information, 0.000000. The first distractor averages payoffs at posteriors with made-up weights; the second is the perfect-information path less the cost; the third mixes EVPI with the cost.'),
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 7, 'A learner restates the Ekene survey for FIN at a cost of 9000000.000000 and changes nothing else. What does the engine return?', '["EVII still 6745331.458602, less the cost -2254668.541398: the information costs more than it is worth", "EVII falls to -2254668.541398, because the stated cost is subtracted from each signal''s EMV before weighting", "A refusal naming information.cost, because a survey dearer than its own EVII cannot be stated in the call", "EVII rises to 9000000.000000, since the engine values the survey at whatever cost the call has stated"]'::jsonb, 0, 'The cost does not change what the signal tells FIN or what FIN does after it; it is subtracted at the end. On info-ekene-too-dear EVII is 6745331.458602 and EVII less the cost is -2254668.541398, with the reason that the information costs more than it is worth (engine). The call is a result, and no field is refused.'),
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 8, 'On info-uninformative both signals carry likelihoods of 50.000000 percent given success and 50.000000 percent given a dry hole, and the stated cost is 0.000000. Which outcome does the engine report?', '["A refusal naming information.signals, since equal likelihoods tell nothing", "A refusal naming information.cost, since a cost of 0.000000 is out of range", "A result with EVII 0.000000 and the reason that the information is worth exactly its cost", "A result with EVII equal to FIN''s EVPI of 14393775.278136"]'::jsonb, 2, 'After either signal the chance of success stays 25.000000 percent, FIN declines after both, and EVII is 0.000000 (engine). The comparison lands exactly on its edge and the engine says so in words: the information is worth exactly its cost. That is a result of a successful call; neither the signals nor the cost is refused, and EVII sits far below EVPI.'),
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 9, 'An informationValue call states one signal only, labelled a, with likelihoods [100, 100]. The engine''s own words in reply are which of these?', '["information.signals must have likelihoodsPct[0] summing to 100 over the signals (P(signal | success)); got a sum of 95", "information.signals[0].likelihoodsPct must be an array [P(signal | success), P(signal | dry hole)] in per cent; got [75]", "information.signals must have at most 10 entries; got 11", "information.signals must be an array of at least 2 signals; got [{\"label\":\"a\",\"likelihoodsPct\":[100,100]}]"]'::jsonb, 3, 'One signal tells nothing, so the engine refuses the array by its length and prints the whole array back, in its own words: information.signals must be an array of at least 2 signals. The summing message answers a likelihood column that does not sum to 100; the array message with got [75] answers a signal with one likelihood; the at-most-10 message answers eleven signals, above the cap of 10.'),
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 10, 'The engine refuses a signal set with this message: information.signals must have likelihoodsPct[0] summing to 100 over the signals (P(signal | success)); got a sum of 95. Which rule failed?', '["The two likelihoods of each signal, given success and given a dry hole, must add to 100 for that signal", "The chances of every signal given success must add to 100 across the signals", "The chance of success must be 100 less the chance of a dry hole", "The engine''s own signal chances must add to 100 before weighting"]'::jsonb, 1, 'likelihoodsPct[0] is P(signal | success), and the rule is a column rule: summed over the signals it must reach 100, because some signal is always returned when the well succeeds. A signal''s own pair need not add to 100 (the Ekene pairs happen to, and 50 with 50 does too). The chance of success is one stated input, and the signal chances are computed by the engine, so neither can be the failed rule.'),
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 11, 'A caller asks informationValue to value the survey for side "partner". What comes back?', '["side must be one of \"farmor\", \"farminee\"; got \"partner\"", "side must be the id of a licence party (EKO, PA); got \"partner\"", "side is not an accepted key; the accepted keys at the top level are parties, farmor, farminee", "A result for PA, the other licence party, whose EMV without information is 0.000000 on the deal"]'::jsonb, 0, 'The engine values one side per call, holds no default side and names the two it accepts, in its own words: side must be one of "farmor", "farminee"; got "partner". It does not read a party id for the side, side is an accepted key, and no position is built for the other licence party.'),
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 12, 'On info-ekene-farmor, which action does EKO take after a bright amplitude signal, and with what EMV?', '["Farm out on the stated terms, with an EMV of 3858013.481672 after the signal", "Walk away, with an EMV of 0.000000", "Drill alone, with an EMV of 64837617.964633", "Farm out on the stated terms, with an EMV of 17987550.556271 after the signal"]'::jsonb, 2, 'At the posterior of 50.000000 percent the engine rolls EKO''s three actions back and drilling alone wins at 64837617.964633 (engine). 3858013.481672 is EKO''s EMV after a dim signal, where farming out is best; 17987550.556271 is FIN''s farm in EMV after a bright signal, a different position; walking away is never best at that posterior.'),
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 13, 'The same Ekene survey is worth 6892331.458602 to EKO and 6745331.458602 to FIN before its cost. What does the course give as the reason the two figures differ?', '["The engine charges the survey''s cost to EKO alone, as the operator that would shoot it", "The farmor''s EVII is taken at the prior chance and the farminee''s at the posterior chance", "Each side values the survey on its own actions and payoffs under the deal", "A Monte Carlo draw of the two signals returns a different estimate for each side''s call"]'::jsonb, 2, 'The course states it plainly: the two sides value the same information differently because their actions and payoffs differ. EKO has three actions (drill alone, farm out, walk away), FIN two (farm in, decline). Each call subtracts the stated cost from its own side''s EVII, both use the same prior and posteriors, and informationValue draws nothing: evpi and evii are the canonical decision tree functions.'),
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 14, 'On the Ekene deal stated with the farmor-side overrun rule, an informationValue call gives FIN a share paid of 31 percent. Which statement matches what the engine does?', '["It returns FIN''s EVII on the stated terms and leaves the share paid unread", "It refuses information.cost, checking the survey''s cost before the deal", "It returns a result for FIN with a reason saying the carry on the success well is below 0", "It refuses deal.farmineePaysPct, naming a floor of 31.363637, rounded up so it is accepted"]'::jsonb, 3, 'The information call builds the same positions as the deal call, so it applies the same check. The engine''s words: deal.farmineePaysPct must be at or above 31.363637 (rounded up at the sixth decimal so that it is accepted), the share at which the carry is 0 when the farmor side pays the excess ... got 31. The share paid is read, the cost is untouched, and a carry below 0 is refused outright with no values returned.'),
  ('farmout', 'advanced', 'module', 'm01-information-value-to-each-side', 15, 'Where do the EVPI and EVII figures of informationValue come from inside the engine?', '["From evpi and evii of engines/economics/decisionTree.js, with Bayes applied to the stated likelihoods", "From portfolioRiskMetrics of engines/economics/portfolio.js, drawing signals under a stated seed", "From an EMV routine written inside farmout.js for this course, separate from the decision course", "From carryRecovery of engines/economics/jointVenture.js, the ledger the farm-in hands over"]'::jsonb, 0, 'The engine''s basis names its source: evpi and evii from engines/economics/decisionTree.js (Bayes from the stated likelihoods, so the signal chances and posteriors are consistent by construction). farmout.js carries no decision tree or Monte Carlo code of its own; portfolio.js is the risk view''s source, and jointVenture.js serves the carry and the back-in.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 1, 'Which figures of a riskSharing call are closed form, the same on any machine whatever the seed?', '["The chance of a loss and the EMV of each position, read from the stated draws", "The EMV and the standard deviation of each position", "The low case and the high case, since both are labelled by the canonical percentile module", "Every figure the call returns, because the seed is a stated input with no default"]'::jsonb, 1, 'The engine''s basis says it: EMV and standard deviation closed form (success/failure mixtures, equal pairwise correlation); the chance of a loss and the low and high cases from its seeded Monte Carlo. The seed makes the draws repeatable on any machine, yet the chance of a loss and the P90 and P10 cases stay estimates; the percentile labels name the cases and compute nothing.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 2, 'On risk-ekene, what happens to EKO''s standard deviation when it farms out 30.000000 percent of Ekene Deep to FIN?', '["It rises from 46115911.128875 alone to 80399735.584206, the cash adding spread", "It stays at 80399735.584206, the prospect''s own spread", "It falls to 23848.480035, the Penn State farm out spread", "It falls from 80399735.584206 alone to 46115911.128875 after the deal"]'::jsonb, 3, 'Drilling alone EKO carries 80399735.584206; after the farm-out it holds 40.000000 percent of the prospect and a certain cash holding, and the closed-form standard deviation is 46115911.128875 (engine). The certain cash has a standard deviation of 0 and adds none. 23848.480035 is the Penn State farm out position on risk-psu, a different problem.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 3, 'With seed 20271111 and 20000 draws, what chance of a loss does the engine print for EKO drilling Ekene Deep alone, and how does the course read it?', '["0.752450, an estimate from the stated draws of a loss chance whose exact value is the dry-hole chance 0.750000", "0.750000, computed exactly in closed form by the engine from the chance of success of 25.000000 percent", "0.747650, the exact chance of a loss for EKO drilling alone, since both positions share one seed", "0.752450, the exact chance of a loss for this position, so any seed prints it the same on any machine"]'::jsonb, 0, 'The engine counts losses in 20000 seeded draws and prints 0.752450 (engine). Both Ekene positions lose on a dry hole and on nothing else, so the chance they estimate is 100 less 25.000000 percent, over 100: 0.750000 (derived); the engine does not return that figure itself. 0.747650 is the estimate for the position after the farm-out. The same seed and draws repeat 0.752450, and another seed prints another estimate.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 4, 'The course says the two Ekene estimates, 0.752450 and 0.747650, each sit within 0.015309 of 0.750000. What is 0.015309?', '["A course tolerance on every graded field", "The gap between the two positions'' estimates", "Five standard errors of a proportion at a chance of 0.750000 over 20000 draws", "One standard deviation of the chance of a loss across seeds the engine has sampled"]'::jsonb, 2, 'The course derives it: five standard errors of a proportion at that chance, with 20000 draws. It is a band for reading sampling noise. No graded field is a draw, so the course tolerance plays no part; the two estimates differ from each other only by accident of the draws, and the engine samples one seed per call.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 5, 'On risk-ekene, EKO after the farm-out holds a certain holding of 5208000.000000. What does that figure stand for?', '["The consideration 10000000.000000 less the assignor fees 392000.000000, all of it received as cash", "The fee of 392000.000000 plus the value of the transaction of 5600000.000000 stated to consentFee", "EKO''s expected carry of 4100000.000000 plus the bonus, with the reimbursement left for later years", "The cash bonus 2000000.000000 plus the reimbursement 3600000.000000, less the assignor fees 392000.000000"]'::jsonb, 3, 'The course derives it: 2000000.000000 + 3600000.000000 - 392000.000000 = 5208000.000000, the cash EKO receives for certain in both outcomes. The carry is already inside EKO''s 40.000000 percent holding (its success value 94500134.816723 and fail cost 12000000.000000), the fee is paid by EKO and never added, and the expected carry is a deal-view figure. The consideration less the fees still counts the carry, which reaches EKO as well costs FIN pays and is no cash.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 6, 'Under the platform''s percentile convention, which label does the engine give the low case of a position?', '["P90, the value the outcome exceeds 90 percent of the time", "P10, the tenth percentile of the outcomes sorted from lowest to highest", "P50, the median of the stated draws, reported as the central case of the position", "P90, the value the outcome falls below 90 percent of the time"]'::jsonb, 0, 'The engine''s label line: p90 is the low case and p10 the high case (probability of exceedance, lib/conventions/percentile.js). P90 is exceeded 90 percent of the time, so it sits low. Calling P10 the low case reverses the convention; a value the outcome falls below 90 percent of the time is a high value; riskSharing reports no P50.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 7, 'A learner reruns the Ekene risk call with a different seed and the same 20000 draws. Which figures can move?', '["Only the EMVs, since the draws feed the average of each position''s outcomes", "The chance of a loss and the low and high cases; the EMVs and standard deviations stay", "Nothing at all, since the seed is part of the stated terms and every figure is closed form", "The standard deviations and EMVs, while the chance of a loss is held by the dry-hole chance"]'::jsonb, 1, 'The seed and the draws move only the estimates: the chance of a loss and the P90 and P10 cases. The EMV and the standard deviation are closed form and depend on neither. A different seed returns different estimates; the same seed and draws return the same ones on any machine.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 8, 'risk-spread-four holds an EMV of 20000000.000000 as one prospect at 100 percent or as 4 independent prospects at 25 percent each. What does the engine return for the spread?', '["53443895.816080 for the one prospect and 106887791.632160 for the four, the four adding spread", "106887791.632160 for both, each prospect''s spread untouched", "82158383.625775 for the four, sharing one latent driver", "106887791.632160 for the one prospect and 53443895.816080 for the four"]'::jsonb, 3, 'With correlation 0.000000 the closed-form standard deviation halves, from 106887791.632160 to 53443895.816080 (engine), at the same EMV. 82158383.625775 is the four prospects with a stated correlation of 0.500000 (risk-correlated), a different call.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 9, 'Four prospects at 25 percent each are stated with a correlation of 0.500000 on risk-correlated. What closed-form standard deviation does the engine return?', '["53443895.816080, since correlation moves only the drawn estimates and leaves the spread", "106887791.632160, since a correlation above 0 makes four prospects act as one", "82158383.625775, above the 53443895.816080 of the same four stated independent", "92230348.163821, the P10 high case of the four independent prospects drawn at seed 11"]'::jsonb, 2, 'The correlation moves the closed-form standard deviation as well as the estimates: 82158383.625775 at 0.500000 against 53443895.816080 independent (engine). Correlated prospects tend to succeed and fail together, so spreading removes less risk. 92230348.163821 is a drawn high case, no standard deviation.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 10, 'A risk call is sent with no seed. In its own words, what does the engine return?', '["seed must be an integer from 0 to 4294967295 (stated; no default); got nothing", "iterations must be an integer from 1 to 200000 (stated; no default); got 200001", "correlation must be a number from 0 to 1 (the correlation of the latent drivers; stated, no default); got -0.1", "positions[0].holdings[0].successStdDev must be a finite number at or above 0; got nothing"]'::jsonb, 0, 'The seed is a stated input with no default, and the engine refuses its absence by name: seed must be an integer from 0 to 4294967295 (stated; no default); got nothing. The other three are the engine''s messages for too many draws, a correlation below 0 and a holding with no standard deviation.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 11, 'A risk call states 200000 draws over positions holding 3 holdings in all. Which refusal comes back?', '["iterations must be an integer from 1 to 200000 (stated; no default); got 200000", "positions must have at most 10 entries; got 3", "iterations must be at most 166666 for 3 holdings in all (iterations x holdings at most 500000); got 200000", "positions[0].holdings must have at most 50 entries; got 200000"]'::jsonb, 2, '200000 draws is inside the draw cap, so the first rule passes; the draw work rule then applies, draws times holdings over all positions at most 500000, and the engine names the most draws three holdings allow: 166666. Three positions or holdings are far inside the caps of 10 positions and 50 holdings.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 12, 'Which correlation does riskSharing refuse?', '["1, since a correlation of 1 makes every holding the same bet", "-0.1, below the stated range from 0 to 1", "0, since independent latent drivers need no correlation stated", "0.500000, since only 0 and 1 are accepted for the latent drivers"]'::jsonb, 1, 'The engine''s words: correlation must be a number from 0 to 1 (the correlation of the latent drivers; stated, no default); got -0.1. 0 is accepted and is what risk-ekene states; 0.500000 is accepted on risk-correlated; 1 lies at the top of the stated range.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 13, 'On risk-psu, the drill yourself or farm out problem of Penn State EME 801, Lesson 6 (numbers only, CC BY-NC-SA 4.0), why does the farm out position show a chance of a loss of 0.000000 with seed 7 and 50000 draws?', '["Its EMV of 17500.000000 is above the drill yourself EMV of 12500.000000", "The seed of 7 happens to draw no dry hole in 50000 draws of that position", "Its standard deviation of 23848.480035 is too small to reach any loss", "Its dry-hole payoff is 0.000000, so no outcome of the position is a loss"]'::jsonb, 3, 'The farm out pays 0.000000 on a dry hole and 50000.000000 on a producer, so it can never lose; the estimate of 0.000000 reflects the payoffs. A higher EMV or a small spread says nothing about losses, and the drill yourself position in the same draws is estimated to lose 0.651800 of the time, so dry holes are drawn.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 14, 'Which risk-view figures does any capstone of this course grade?', '["None of them, since the course grades no Monte Carlo draw of any kind", "The chance of a loss, since a stated seed makes the draw the same on any machine", "The low case alone, since P90 prints the same as the dry-hole payoff on risk-ekene", "Every figure of risk-ekene, each printed to six decimals"]'::jsonb, 0, 'The course is explicit: no graded figure is a Monte Carlo draw, and the chance of a loss and the low and high cases are taught and never graded. A stated seed repeats a draw; it does not make a sample a return value on fixed terms. A P90 that prints like a payoff is still a percentile of draws.'),
  ('farmout', 'advanced', 'module', 'm02-risk-sharing', 15, 'With seed 20271111 and 20000 draws, how does the farm-out move EKO''s low case (P90) on risk-ekene?', '["From -6792000.000000 alone to -28000000.000000 after, the deal deepening EKO''s worst case", "From -28000000.000000 alone to -6792000.000000 after, estimates from the stated draws", "From -28000000.000000 alone to -12000000.000000 after, the fail cost of the 40 percent holding", "It stays at -28000000.000000, since both positions lose on the same dry hole"]'::jsonb, 1, 'The draws put EKO''s low case at -28000000.000000 alone and -6792000.000000 after the farm-out (engine, seed 20271111, 20000 draws). After the deal EKO''s dry-hole outcome is the fail cost 12000000.000000 offset by the certain cash 5208000.000000, so the low case sits at -6792000.000000 and the fail cost alone is too low. The same dry hole costs EKO less after the deal.'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 1, 'At a 25.000000 percent chance of success, the Ekene Deep 100 percent position has a risked EMV of 26312584.260452. What risked value per percent of working interest does the engine return?', '["2252503.370418, the success-case value less the success well cost, over 100", "533333.333333, the stated price of 16000000.000000 divided by 30 percent", "7893775.278136, the risked value of the 30 percent working interest priced", "263125.842605, the 100 percent EMV divided by 100"]'::jsonb, 3, 'The engine''s rule: value per percent = the 100% figure / 100, the risked figure being the EMV of the 100% position. 26312584.260452 / 100 is 263125.842605 (engine). 2252503.370418 is the success-case figure per percent; 533333.333333 is the stated price per percent; 7893775.278136 is the value of 30.000000 percent on the risked basis.'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 2, 'What does the engine give as the 100 percent success payoff of Ekene Deep in the price view?', '["271250337.041807, the canonical npv of the stated net cash flows to 2027 with no well cost taken off", "225250337.041807, the success-case value 271250337.041807 less the 46000000.000000 success well", "26312584.260452, the risked EMV of the whole prospect at 25.000000 percent", "157675235.929265, EKO''s success payoff drilling alone with its 70.000000 percent"]'::jsonb, 1, 'The 100 percent position on a success is the success-case value less the success well cost: 271250337.041807 - 46000000.000000 = 225250337.041807 (engine). The npv alone omits the well; 26312584.260452 is the risked EMV of that position, weighing in the dry hole; 157675235.929265 is EKO''s 70.000000 percent position in the deal view.'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 3, 'On interest-ekene-success-case the same 30.000000 percent is priced on the success-case basis. What is the working interest worth, and which per-percent tiles move against the risked call?', '["67575101.112542; both per-percent figures stay, only the value of the working interest follows the basis", "7893775.278136; the basis only relabels the value the engine already reported on the risked call", "67575101.112542; the risked per-percent tile falls to 0.000000 once the success case is chosen", "2252503.370418; the value of the working interest is the success-case figure for one percent"]'::jsonb, 0, 'The engine computes both per-percent figures on every call (263125.842605 risked, 2252503.370418 success case), and the stated basis decides which values the working interest: 30.000000 x 2252503.370418 = 67575101.112542 (engine). 7893775.278136 is the risked value; no tile falls to 0; 2252503.370418 is one percent.'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 4, 'The Ekene price is 16000000.000000 for 30.000000 percent. What ratio does the engine report against the risked value per percent?', '["0.236774", "1.125000", "2.026914", "1.333333"]'::jsonb, 2, '533333.333333 a percent over the risked 263125.842605 is 2.026914 (engine), a ratio of a stated price to a computed value, reported only. 0.236774 is the same price against the success-case value per percent; 1.125000 is the producing interest''s ratio; 1.333333 is the promote ratio of the Ekene well, 40 over 30.'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 5, 'Which statement describes the transaction ratio 2.026914 the way the engine''s own metrics line does?', '["A ratio of stated inputs to a computed value, reported only: no market value is asserted", "The market premium buyers pay for Ekene-type prospects, as a multiple of the risked value", "The promote ratio of the Ekene farm-in, the share paid over the working interest earned", "A forecast of what a partner will pay, since it rests on the stated chance of success"]'::jsonb, 0, 'The engine''s line: transaction metrics are ratios of stated inputs (price, volumes, rates), reported only: no market value is asserted. The course adds that none of its computed figures is a forecast of what a partner will pay or a statement of market value. The promote ratio is a different figure (1.333333 on the Ekene well).'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 6, 'On interest-negative-emv the risked value per percent is -300000.000000 and a price of 1000000.000000 is stated for 25 percent. What does the engine do with the price-to-value ratio?', '["Refuses transaction.price, since a price above a negative value cannot be stated", "Returns 40000.000000 as the ratio, the stated price per percent taken alone", "Returns the ratio against the success-case figure of 1600000.000000 in its place", "Returns none, with a reason naming the value at or below 0"]'::jsonb, 3, 'The engine''s reason: stated price 1000000 for 25%: 40000 a percent, 4000000 for 100%; no price-to-value ratio, the risked value per percent being -300000, at or below 0. It still reports the price per percent; it neither refuses the price nor switches to the other basis, and 40000.000000 is the price per percent, which it prints as a price.'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 7, 'The fixture states 120.000000 MMboe of 2C (contingent, best estimate) for the whole prospect. What price per MMboe does the engine print for the 30.000000 percent working interest?', '["533333.333333, the stated price per percent of working interest priced", "444444.444444, the price over 36.000000 MMboe net to the working interest", "263125.842605, the risked value per percent, read as a price per MMboe", "53333333.333333, the stated price for the working interest scaled up to 100 percent"]'::jsonb, 1, 'The volume net to the working interest is 30.000000 percent of 120.000000, 36.000000 MMboe, and the engine divides the stated price by it: 444444.444444 (engine). 533333.333333 is the price per percent, 53333333.333333 the price scaled to 100 percent and 263125.842605 the risked value per percent, none of them per MMboe; the engine applies no reserve adjustment, the category being a stated label.'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 8, 'interest-production-metric prices a 20.000000 percent working interest in a producing field with a chance of success of 100 and a success well cost of 0. Why do the two per-percent figures agree?', '["The engine sets both figures to the price per percent when a flowing rate is stated", "A producing field is valued on the success-case basis only, so the risked tile copies it", "With no dry hole and no well cost the risked EMV equals the success case, both 800000.000000 a percent", "The rate of 1000.000000 boe/d replaces the success-case value in both calculations"]'::jsonb, 2, 'The engine''s reason: 100% position: success 80000000 (success-case value 80000000 less the success well cost 0), dry hole 0; risked EMV at 100% 80000000. A chance of 100 leaves no dry hole to weigh, so risked and success case both print 800000.000000 a percent. The price per percent is 900000.000000, and the stated rate only feeds the price per flowing unit.'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 9, 'An interestValue call states valueBasis "unrisked". Which message does the engine return?', '["valueBasis is not an accepted key; the accepted keys are project, interestPct, transaction", "valueBasis must be one of \"risked\", \"success-case\"; got \"unrisked\"", "valueBasis must be \"risked\" when a chance of success below 100 is stated; got \"unrisked\"", "interestPct must be a number above 0 and at most 100; got \"unrisked\""]'::jsonb, 1, 'The engine holds no basis of its own and names the two it accepts, in its own words: valueBasis must be one of "risked", "success-case"; got "unrisked". valueBasis is an accepted key; the engine ties no basis to the chance of success; the interestPct message answers a working interest of 0.'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 10, 'A price call states a transaction with a volume unit of boe and no reserves. What does the engine return?', '["transaction.volumeUnit must be a non-empty string; got nothing", "transaction.reserves must have at most 10 entries; got 11", "A price per boe of 0.000000, since no volume is stated under the unit", "transaction.volumeUnit must be left out when no reserves are stated; got \"boe\""]'::jsonb, 3, 'A unit needs a volume and a volume needs a unit; the engine refuses each half alone. Here the unit arrives without reserves, so the engine''s words are: transaction.volumeUnit must be left out when no reserves are stated; got "boe". The non-empty-string message answers reserves stated with no unit; the cap of 10 answers eleven categories.'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 11, 'Take the risked value of the 30.000000 percent working interest, 7893775.278136, less the bonus of 2000000.000000 and the reimbursement of 3600000.000000. Which figure does the course say that gives?', '["2293775.278136, which prints as FIN''s EMV in deal-ekene paying 30.000000 percent for 30.000000", "-1806224.721864, FIN''s EMV in deal-ekene paying 40.000000 percent for 30.000000", "1414224.721864, the rise in EKO''s EMV from farming out on the stated Ekene terms", "4293775.278136, FIN''s EMV paying its own share with no bonus stated at all"]'::jsonb, 0, 'The course derives the identity: 7893775.278136 less 2000000.000000 and 3600000.000000 is 2293775.278136, and FIN''s EMV at the first breakpoint, paying only its own share, prints as 2293775.278136 (engine). The two agree at the six decimals the course prints; the engine''s doubles differ in their last digits, so the course calls them alike in print. -1806224.721864 is FIN at the 40.000000 percent asked; 1414224.721864 is the rise in EKO''s EMV; 4293775.278136 is the first breakpoint of deal-ekene-bonus-zero, whose cash bonus is 0 while the reimbursement stays.'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 12, 'Priced as a 10.000000 percent working interest, the drill yourself or farm out figures of Penn State EME 801, Lesson 6 (numbers only) give a risked value per percent of what?', '["5000.000000, the success-case figure per percent", "1250.000000, the risked value of the 10.000000 percent working interest", "125.000000, the 100 percent EMV of 12500.000000 over 100", "12500.000000, the 100 percent EMV itself before any division by 100"]'::jsonb, 2, 'interest-psu-10pct: 100 percent success 500000.000000, dry hole -250000.000000, EMV at 35.000000 percent 12500.000000; risked per percent 125.000000 and the working interest worth 1250.000000 (engine). 5000.000000 is the success-case figure per percent; 12500.000000 is the 100 percent EMV before it is divided by 100.'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 13, 'A learner sets the working interest priced to 0 on the Ekene Deep price. What comes back?', '["A value of the working interest of 0.000000, with both per-percent tiles unchanged", "valueBasis must be one of \"risked\", \"success-case\"; got nothing", "A price per percent of none, with a reason saying the working interest is 0", "interestPct must be a number above 0 and at most 100; got 0"]'::jsonb, 3, 'The working interest priced is a stated input above 0 and at most 100, and the engine refuses 0 by name: interestPct must be a number above 0 and at most 100; got 0. No result is returned, so no tile prints; the valueBasis message answers a missing basis.'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 14, 'Which reading of a reserve category does the engine apply when it prices 2C (contingent, best estimate)?', '["None: it divides the stated price by the stated volume whatever the label says", "Risking the 2C volume by the stated chance of success before dividing the price", "A conversion of 2C to 2P at a stated factor, as its published classification requires", "It refuses any category that is not a proved reserve under the published rules"]'::jsonb, 0, 'The source line: the reserve category and its volume are stated as the user classifies them. The engine classifies nothing: 2C is the fixture''s label, and the price per MMboe is the stated price over the stated volume net to the working interest. It risks, converts and refuses no category.'),
  ('farmout', 'advanced', 'module', 'm03-pricing-an-interest', 15, 'HMRC''s manual says "The value of the right will need to reflect the degree of probability that future benefits will accrue as well as their extent" (HMRC Oil Taxation Manual OT30131). Which basis of the price view weighs that probability?', '["The success-case basis, the success-case value less the success well cost over 100", "The risked basis, which rolls both outcomes back at the stated chance", "Both bases alike, since each is computed on every call the engine answers", "Neither; the chance enters only the deal view''s EMVs"]'::jsonb, 1, 'The risked figure rolls the success and the dry hole back at the stated chance of success, so it reflects the probability; the success-case figure assumes the well succeeds and reflects the extent alone. The engine computes both every time, and the chance of success is an input of interestValue itself.'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 1, 'After the Ekene farm-in EKO holds a 40.000000 percent participating interest, and FIN carries 50.000000 percent of EKO''s cost share. What carried interest does the engine report?', '["20.000000 points, half of EKO''s 40.000000 percent", "50.000000 points, the stated carriedPct itself", "30.000000 points, FIN''s own vested interest after the farm-in", "35.000000 points, the whole interest earned across both wells"]'::jsonb, 0, 'The engine reports a carried interest of 20.000000 points (engine): the carried share of the farmor''s cost share, 50.000000 percent of 40.000000. carriedPct is the stated share of the cost share, FIN''s 30.000000 percent is its own vested interest, and 35.000000 belongs to the drill-to-earn case, a different deal.'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 2, 'In 2029 the Ekene development costs 240000000 gross. With EKO at 40 and a stated carriedPct of 50, what carried cost does the engine''s rule add that year?', '["144000000.000000, the carried cost of all three years", "24000000.000000, the carried cost the ledger adds in 2031", "48000000.000000, cost x 40 x 50 / 10,000", "72000000.000000, the gross cost times PA''s 30 percent"]'::jsonb, 2, 'The engine''s rule: carried cost = cost x participating interest x carriedPct / 10,000. 240000000 x 40 x 50 / 10,000 = 48000000.000000, the 2029 carried cost added (engine). 144000000.000000 is the carried cost of 2029 to 2031 together; 24000000.000000 is the carried cost added in 2031, a later year; 72000000.000000 is PA''s own 30 percent share of the 2029 cost, which nobody carries.'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 3, 'Under the compound uplift of 8.000000 percent a year, what does the engine add in 2031 on the Ekene development carry, and on what?', '["9600000.000000, on the outstanding principal of 120000000.000000", "9907200.000000, on the whole opening balance of 123840000.000000", "11520000.000000, on the principal of 144000000.000000 after the 2031 cost", "12619776.000000, on the 2032 opening balance"]'::jsonb, 1, 'The compound basis: 8% a year on the opening balance, compounded yearly; a year''s new cost earns none in its own year. 2031 opens at 123840000.000000, which carries the 2030 uplift, so it adds 9907200.000000 (engine). 9600000.000000 is the simple uplift of 2031 on principal alone; 11520000.000000 and 12619776.000000 are the 2032 simple and compound uplifts.'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 4, 'At the same 8.000000 percent a year, how do the simple and the compound uplift compare over the life of the Ekene development carry?', '["Both add 46353141.996585 and recover in 2036 alike", "Simple adds 46353141.996585 and compound 44438966.681600, compounding lagging a year", "Simple adds 44438966.681600 and recovers in 2035, a year before the compound ledger", "Simple adds 44438966.681600 and compound 46353141.996585; both recover in 2036"]'::jsonb, 3, 'The two printed ledgers (engine): the simple form adds 44438966.681600 in all, the compound form 46353141.996585, and both recover the carry in 2036. Compound charges the uplift on the whole opening balance, which carries earlier uplift, so it adds more; simple charges the principal alone.'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 5, 'In 2036 the compound Ekene carry is due 7633141.996585 and 34073600.000000 is available. What does the engine record for the year?', '["34073600.000000 recovered, the full available share, and EKO receives 34073600.000000", "7633141.996585 recovered and EKO receives 34073600.000000, the available half only", "68147200.000000 recovered, EKO''s whole share of the entitlement that year", "7633141.996585 recovered, closing 0.000000, and EKO receives 60514058.003415"]'::jsonb, 3, 'Recovered = min(available, due, cap left): 7633141.996585 closes the balance. EKO receives its share of the entitlement less the recovery, 68147200.000000 - 7633141.996585 = 60514058.003415 (engine); the available half caps the recovery and does not limit what EKO keeps.'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 6, 'What does available for recovery mean on the Ekene carry ledger in 2032, when EKO''s share of the entitlement is 100000000.000000?', '["50000000.000000, the stated 50.000000 percent of EKO''s share that the carry may take", "100000000.000000, EKO''s whole share, since the balance due is larger than it", "170366976.000000, the balance due, which the engine recovers in full once production starts", "30000000.000000, FIN''s 30.000000 percent of EKO''s share of the entitlement"]'::jsonb, 0, 'The rule: recovered = min(carried party''s entitlement share x recoverFromPct / 100, due, cap left). With recoverFromPct 50.000000, 50000000.000000 of the 100000000.000000 is available, and all of it is recovered against 170366976.000000 due (engine).'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 7, 'On devcarry-ekene-simple-ot18360, how does the engine split the 50000000.000000 recovered in 2032?', '["25040000.000000 of principal first, then 24960000.000000 of accrued simple interest, as HMRC''s manual prescribes", "50000000.000000 of principal, leaving 24960000.000000 of accrued simple interest to earn an uplift of its own", "24960000.000000 of accrued simple interest first, then 25040000.000000 of principal, as the engine''s stated reading", "An even split of the 50000000.000000, since HMRC''s manual names no order of payment"]'::jsonb, 2, 'The engine''s reason: the 50000000 recovered pays the accrued interest 24960000 first, then 25040000 of principal. HMRC''s manual says only that the recovery usually includes an addition representing simple interest and does not say which is paid first, so the order is a reading the engine states. Under its rule accrued simple interest earns none.'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 8, 'devcarry-ekene-none-capped states no uplift and a cap of 100000000.000000 on the carry recovery. What does the engine return?', '["144000000.000000 recovered, the whole carried cost, the cap covering an uplift only", "100000000.000000 recovered and 44000000.000000 written off", "100000000.000000 recovered and 44000000.000000 carried forward past 2045", "A refusal of cap, since a cap below the carried cost would leave it unrecovered"]'::jsonb, 1, 'The reason: 2033: the stated cap 100000000 is reached with 50000000 recovered this year; the rest, 44000000, is written off. The cap binds the recovery itself, the rest is written off with nothing carried forward, and a cap below the carried cost is a stated term the engine accepts.'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 9, 'On devcarry-recovered-exactly the balance due in 2031 is 400.000000 and 400.000000 is available. Which reason does the engine give?', '["the balance 400 is recovered exactly by the 400 available; the carried party receives 0 of its share 400", "the balance 400 is recovered with 400 of the 400 available; 0 is carried to the next year", "400 recovered of 400 due; 0 carried to 2032, and the carry stays open for a further year", "the stated cap 400 is reached with 400 recovered this year; the rest, 0, is written off"]'::jsonb, 0, 'The engine names the boundary in words: the balance 400 is recovered exactly by the 400 available; the carried party receives 0 of its share 400. The carry closes that year at 0.000000; the other lines are the shapes of an ordinary recovery, a year still open and a cap, none of which applies.'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 10, 'A developmentCarry call states earnedPct 70 on the Ekene licence, where EKO holds 70 percent. What comes back?', '["earnedPct must be at most the farmor''s interest 70; got 80", "carriedPct must be a number above 0 and at most 100; got 0", "A ledger with a carried interest of 0.000000 points, nothing to recover, and EKO paying none of its development costs", "earnedPct must be below the farmor''s interest 70 (the farmor keeps a carried interest); got 70"]'::jsonb, 3, 'A development carry needs a farmor that keeps a carried interest, so earning its whole 70 is refused in the engine''s own words: earnedPct must be below the farmor''s interest 70 (the farmor keeps a carried interest); got 70. The at-most-70 message is backInRight''s refusal of 80; the carriedPct message answers a carry of 0.'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 11, 'A developmentCarry call leaves the uplift out. Which message is the engine''s?', '["uplift must be an object { type, ratePct } with type \"simple\" when HMRC OT18360 applies; got nothing", "uplift must be an object { type } with type \"none\", \"simple\", \"compound\" or \"multiple\" (no default); got nothing", "recoverFromPct must be a number above 0 and at most 100; got nothing", "A ledger with no uplift, since the cost alone is recovered when none is stated"]'::jsonb, 1, 'The uplift is a required input with no default; the engine names the four forms it accepts, in its own words: uplift must be an object { type } with type "none", "simple", "compound" or "multiple" (no default); got nothing. HMRC''s usual simple interest is described in the engine''s note and imposed on no call; the recoverFromPct message answers a missing recovery share.'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 12, 'On backin-ekene EKO backs in from 40.000000 to 45.000000 percent under the contract basis, with 480000000.000000 of refundable costs. What refund does EKO pay?', '["46000000.000000, the exploration well the contract basis excludes", "12000000.000000, the part PA receives for the 2.500000 points it cedes", "24000000.000000, 5 percent of the refundable costs", "144000000.000000, 30 percent of the refundable costs"]'::jsonb, 2, 'The rule: refund = (target - current) / 100 x refundable costs: 5 percent of 480000000.000000 is 24000000.000000 (engine). The 46000000.000000 exploration well is excluded and is no refund; 12000000.000000 is one party''s half of the refund; 144000000.000000 is the refund of PA''s back-in from 30 to 60 on backin-ekene-pia.'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 13, 'After EKO backs in to 45.000000 percent on backin-ekene, what participating interest does PA hold?', '["27.500000 percent, its 30.000000 x 55 / 60", "30.000000 percent, since the back-in party takes its gain from FIN alone", "25.000000 percent, since PA cedes the whole 5 points of EKO''s gain", "22.857143 percent, the interest EKO keeps on the PIA back-in"]'::jsonb, 0, 'The rule: new interest of another party = old x (100 - target) / (100 - current); the reason says the others keep 55 / 60 of their interests. PA''s 30.000000 becomes 27.500000 and FIN''s likewise, each ceding 2.500000 (engine). 22.857143 is EKO''s interest after PA''s back-in on backin-ekene-pia.'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 14, 'Under basis pia-s85-4, why does the engine exclude the 46000000.000000 Ekene Deep-1 exploration well from the refundable costs?', '["A dry hole, and the Act refunds only the cost of wells that found oil and were tested and suspended", "The contract basis lists exploration as refundable and the Act basis removes the list", "FIN paid for the exploration well under the farm-in, so no party can claim it", "PIA s.85(4)(c) allows development and production costs only, and exploration is neither"]'::jsonb, 3, 'The engine''s reason: Ekene Deep-1 exploration well: 46000000 (exploration) is not refundable (PIA s.85(4)(c): development and production costs only, no bonuses, penalties, interest, premium or markups). The Ekene well cost 46000000.000000 as a success, and on backin-ekene the contract basis excludes it too.'),
  ('farmout', 'advanced', 'module', 'm04-carries-and-back-ins-after-the-farm-in', 15, 'A backInRight call names EKO with a target of 35 percent while EKO holds 40 after the farm-in. What does the engine return?', '["backIn.party must be one of \"EKO\", \"PA\", \"FIN\"; got \"NOC\"", "backIn.targetPct must be above the back-in party''s current interest 40; got 35", "A back-out in which EKO cedes 5 points to PA and FIN in proportion to their participating interests", "earnedPct must be at most the farmor''s interest 70; got 80"]'::jsonb, 1, 'A back-in raises the back-in party''s participating interest, so a target at or below the current one is refused in the engine''s own words: backIn.targetPct must be above the back-in party''s current interest 40; got 35. The party message answers NOC, the earnedPct message answers 80, and the engine computes no back-out.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 1, 'The engine states that the success-case value is at the valuation date; well costs, bonus, reimbursement and fees fall at the valuation date, undiscounted. Where does that reading act?', '["On the consent fee alone, whose day count starts on the date of the valuation", "On every EMV of the deal view, whose positions set those costs beside the discounted value", "On the risk view''s draws alone, whose seed is fixed at the valuation date", "Nowhere a figure depends on it, since every cost is first discounted to the base year by the canonical npv"]'::jsonb, 1, 'The course says the valuation timing acts on every EMV of the deal: a deal whose well costs, bonus, reimbursement and fees fell a year after the valuation date would discount them at the success-case rate and give different EMVs. The fee days count from the notification, the draws depend on the seed, and the costs are undiscounted by this very reading.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 2, 'fee-ekene is notified on 2027-05-03 and paid on 2027-07-30. How many days does the engine count, and what status does it return?', '["91 days, within-grace, the notification day and the payment day both counted", "88 days, within-grace, since the payment falls in the third month", "90 days, on-time, rounded up to the regulation''s own period", "88 days, on-time"]'::jsonb, 3, 'The engine counts from the notification date to the payment date, the notification day not counted: 88 days, and its reason reads paid 88 days after the notification: within the 90 days of reg. 19(7) (engine). The engine counts neither the notification day nor any extra day; it rounds nothing, and 88 is inside the 90 days.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 3, 'Reading two names an alternative day count for reg. 19(7): counting the notification day as well. On the golden case fee-day-90, which figure would that alternative move?', '["The fee: the seven per cent would be charged on the value of the transaction plus one day", "The surcharge: 0.01 percent of the fee would be charged for the notification day itself", "The status: the payment the engine counts as day 90, on time, would fall into the grace days", "Nothing: the engine''s count and the alternative agree on every day the table probes, from day 90 to day 211"]'::jsonb, 2, 'The course states it: counting that day as well would move a payment on day 90 into the grace days. The reading acts only at the day boundaries of the payment rules. The fee is seven per cent of the stated value whatever the dates, and no surcharge runs inside the 90 days or the 30 days of grace.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 4, 'On fee-day-210 the payment comes 90 days after the 90 + 30 days. How does the engine read reg. 19(9)''s surcharge for 90 days failing which the consent is deemed withdrawn?', '["It charges the ninetieth surcharge day, 3528.000000 on the 392000.000000 fee, and deems the consent withdrawn from day 211", "It deems the consent withdrawn on the ninetieth surcharge day itself, so day 210 returns no total paid at all", "It charges 90 days at 39.200000 each and keeps the consent standing on every day after, with the surcharge still running", "It refuses payment.paidOn for any date after day 120, since the regulation''s grace days have then run out"]'::jsonb, 0, 'The engine charges 0.01 percent of the fee a day straight line: 90 days cost 3528.000000 and the consent stands on day 210; on day 211 it returns consent-deemed-withdrawn and no total paid (engine). Withdrawing on the ninetieth day is the other reading, which the course names; the engine refuses no late date, since a withdrawn consent is a result.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 5, 'Reading four names the other order a simple-interest recovery could follow, principal first. What does the course say that order would do, and when does the reading act at all?', '["Leave the ledger as it is, since accrued simple interest earns none under either order of payment", "Lower every year''s uplift, whatever uplift type the carry states in its terms", "Leave more principal outstanding to earn simple interest; it acts only under uplift type simple", "Raise the uplift only under the compound form, where it runs on the whole balance"]'::jsonb, 2, 'The course: paying principal first would leave more principal outstanding to earn interest, and the reading acts only when a carry states uplift type simple. Simple interest runs on the principal alone, so the order moves the ledger; under the compound form the uplift is charged on the whole opening balance, and the order of payment has nothing to act on.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 6, 'Which of these does the course treat as a stated input with its source, and no reading at all?', '["The day count from notification to payment", "The value of the transaction on which the consent fee is charged", "The ninetieth surcharge day of reg. 19(9) and the day of withdrawal", "The valuation timing of well costs, bonus, reimbursement and fees"]'::jsonb, 1, 'The course separates it: the value of the transaction is a stated input (the sum payable to the Assignor stated in the application or contract, or an amount the Commission determines); it is no reading. The engine takes the amount and its source from the caller and charges the gazetted rates on it. The other three are readings the engine states in its bases.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 7, 'The Penn State EME 801, Lesson 6 page labels its payoff table in two ways. How does the course handle that?', '["It treats Table 6.1 and Table 10.1 as two separate tables and checks the engine against each one in turn", "It quotes the page''s own sentence that explains the second label, with the page''s citation", "It calls the table Table 10.1, the label the page uses where it computes the EMVs", "It cites the page and its printed figures and calls the table by its first label, Table 6.1"]'::jsonb, 3, 'The page labels the table as Table 6.1 where it first prints it and refers to it as Table 10.1 when it computes the EMVs and the value at risk from the same figures. The course cites the page and its printed figures and uses the first label. One table carries both labels, and no sentence of the page is quoted anywhere, because its licence is non-commercial and the course is sold.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 8, 'The engine''s farm out EMV on deal-psu-eme801 prints as 17500.000000, and the page prints 17500.000000. What does the course claim about the two?', '["The check passes within 0.000001; the double carries float residue, so no equality is keyed", "Equal, since the engine and the page both print the same six decimals", "Different, by the rounding the page applies to the nearest whole dollar", "They are equal to the last binary digit of the double the engine holds"]'::jsonb, 0, 'The course: the engine''s farm out EMV prints as 17500.000000 at six decimals; the double it holds carries float residue in its last binary digits, and the check passes within 0.000001. Printed alike is not equal, so the course keys the check within its stated bound and claims no equality.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 9, 'The arrangement of regulations at the front of the Assignment of Interests Regulations, 2024 lists 22. General provisions 23. Revocation 24. Interpretation 25. Citation. How does the body number its citation provision?', '["25", "24", "23", "26"]'::jsonb, 3, 'The body prints regulation 23 as guidelines and numbers the citation 26 (AOI Regulations 2024 reg. 26 (the citation, as the body numbers it)). A citation of reg. 25 follows the arrangement, and the body prints no regulation of that number. 24 is Interpretation in both; 23 is Revocation in the arrangement and guidelines in the body.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 10, 'How does the gazette cover of S.I. No. 67 of 2024 list the instrument, and which name does the course use?', '["The cover and the citation both say Nigerian Upstream Petroleum (Assignment of Interests) Regulations, 2024", "The cover says Nigerian Upstream Petroleum (Assignment of Interests) Regulations, 2024; the course uses a shorter name", "The cover says Nigeria Upstream Petroleum (Assignment of Interest) Regulations, 2024; the course uses the citation''s name", "The cover names the instrument by its number alone, S.I. No. 67, and the course takes its name from reg. 1"]'::jsonb, 2, 'The course quotes the cover as 67 Nigeria Upstream Petroleum (Assignment of Interest) Regulations, 2024, a shorter title, while the citation names it the Nigerian Upstream Petroleum (Assignment of Interests) Regulations, 2024, the name this course uses. The course takes the name from the citation provision, which the body numbers 26.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 11, 'Reg. 19(3) and reg. 24 of the 2024 Regulations both define the value of the transaction. How do the two definitions differ?', '["Reg. 19(3) names two sources for the amount; reg. 24 names the Commission''s determination alone", "Reg. 19(3) names the Commission alone; reg. 24 adds the amount stated in the contract as a second source", "Reg. 19(3) sets the fee at seven per cent; reg. 24 sets it at two per cent for every assignment", "They agree word for word, and the course quotes them twice because the body prints them twice"]'::jsonb, 0, 'Reg. 19(3): the amount payable to the assignor stated in the application or contract, or an amount the Commission prescribes. Reg. 24: the amount determined by the Commission to be the value receivable by the Assignor. The engine does not choose between them; it takes the amount and its source as stated inputs. The seven per cent is reg. 19(2), and the two per cent processing fee applies to an intra group transfer.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 12, 'The engine says farmor and farminee. Which word does the Petroleum Industry Act 2021 print for the incoming party in s.94(5)?', '["farminee", "farmee", "Farmer In", "assignee"]'::jsonb, 1, 'The Act says farmee (PIA s.94(5)). HMRC''s manual says Farmer Out and Farmer In (OT30020) and, on another page, the increasing interest party, farmer-in or farmee (OT18320). farminee is the engine''s word, and each text''s own word is quoted as it prints it.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 13, 'Why does the course cite the Penn State EME 801 page for its figures and quote none of its sentences?', '["Its licence, CC BY-NC-SA 4.0, is non-commercial and this course is sold", "Its figures are rounded, so only the engine''s six-decimal figures can be quoted", "It is a licensed model agreement, taught by concept only under the regulatory rule", "Its text is United Kingdom tax guidance, quoted only for concepts under OGL v3.0"]'::jsonb, 0, 'The course''s source table says numbers only: the licence is non-commercial and this course is sold, so no sentence of it is quoted. It is a teaching page and no model agreement; the Open Government Licence text is HMRC''s manual. The engine reproduces the page''s printed EMVs, so rounding is no obstacle.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 14, 'The validation record says no public text prints a farm-in schedule or a break-even promote. Where do those figures of the course come from?', '["A licensed model farm-out agreement, taught by concept and computed by the engine", "The Penn State EME 801 problem, whose break-even promote the page prints", "The stated deal arithmetic, run by the engine on stated terms", "The HMRC manual''s worked farm-in examples"]'::jsonb, 2, 'Its own words: No public text prints a farm-in schedule or a break-even promote: those goldens come from the stated deal arithmetic in the oracle. The course runs that arithmetic through the engine. The one published worked figure is the Penn State problem, whose page prints neither break-even; licensed forms are never a source, and the HMRC pages are quoted for concepts.'),
  ('farmout', 'advanced', 'module', 'm05-readings-and-source-quirks', 15, 'Which capstone fields of the course depend on one of the four readings the engine states?', '["The fee fields alone, since the day count decides whether a surcharge applies at all to the payment", "The development carry balance, since the simple uplift pays accrued interest first in every year", "Every EMV field, since the valuation timing places the costs at the valuation date", "None: every field is the same number under each reading and under its named alternative"]'::jsonb, 3, 'The course is explicit: no graded figure depends on a reading the engine states, and every capstone field is bit-identical under each reading and under the alternative named beside it. Each reading is taught as the engine''s stated choice beside the text it reads.'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 1, 'A farm-out pays EKO a carry, a cash bonus and a reimbursement. Which of them counts in the value of the transaction on which the consent fee is charged, according to the engine?', '["All three, since the consideration is the value the Regulations charge", "The cash alone, the bonus and the reimbursement, 5600000.000000 on Ekene", "The carry alone, since reg. 19(3) names work paid for the assignor", "The engine does not decide; the caller states the amount and its source"]'::jsonb, 3, 'The engine''s own words: the value of the transaction is a stated input ... the engine does not decide which consideration of a farm-out counts. The Ekene fixture happens to state 5600000.000000, the bonus plus the reimbursement; a deal counting the carry would state a larger value and the engine would charge seven per cent of it. Which part counts comes from reg. 19(3) and reg. 24 and the Commission, outside the call.'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 2, 'What does the engine do with the Commission''s metrics for good and valuable consideration under reg. 19(3)(b)?', '["Nothing beyond taking a Commission-determined amount as a stated input", "It applies them to the success-case value to set a Commission-determined amount", "Applies them through the risked value per percent of the interest assigned", "A refusal of a commission-determined source, since the metrics are unpublished"]'::jsonb, 0, 'The course''s list of what the engine does not compute: the Commission''s metrics are not computed, and the engine takes a Commission-determined amount as a stated input (valueSource "commission-determined" is accepted). It derives no amount from any value it computes and refuses no such source.'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 3, 'Which fee of an assignment does the engine leave uncomputed although reg. 19(6) says consent is not granted until it is paid?', '["The processing fee, which reg. 19(2) sets at two per cent of the stated value", "The premium, which reg. 19(2) sets at five per cent of the stated value", "The application fee, which reg. 19(1) leaves to other regulations of the Commission", "The surcharge, which reg. 19(9) sets at 0.01 percent of the fee a day for up to 90 days after the grace"]'::jsonb, 2, 'The course''s list of what the engine does not compute: the application fee, AOI 2024 reg. 19(1), set by other regulations of the Commission; the engine computes nothing for it. The processing fee, the premium and the surcharge are the gazetted figures it does apply, each cited to reg. 19(2) or 19(9).'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 4, 'PIA s.233(10) requires a farm-out agreement to provide for a decommissioning and abandonment plan funded in whole or in part by the incoming parties. What does the engine compute for it?', '["The farminee''s share, at its vested interest times the dry-hole cost", "Nothing; it is taught as a concept only", "A reserve in the farmor''s position, at the stated assignor fees", "The incoming parties'' share, at the stated share paid of each well"]'::jsonb, 1, 'The course''s list of what the engine does not compute: a decommissioning and abandonment plan funded by the incoming parties, PIA s.233(10); the engine does nothing, concept only. A deal team values a farminee''s share of a future abandonment cost outside the call and states it beside the engine''s figures.'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 5, 'What does the engine report about tax on a farm-out deal?', '["Only that the consent fee is not tax deductible; the tax on the deal is not computed", "The hydrocarbon tax on the farmor''s consideration, by PIA s.264(f) on the stated value", "Capital gains on the cash bonus at the rate HMRC''s manual prints for farm-outs", "Companies income tax on the carry, at the rate of PIA s.302(12)(c) on the consideration"]'::jsonb, 0, 'The engine''s basis says the fee is not tax deductible (reg. 19(5); PIA s.95(12)) and that fees paid for assigning rights to another party are not deductible (PIA s.264(f) and s.302(12)(c)). Those sections deny a deduction and set no rate on a deal; HMRC''s manual is United Kingdom guidance quoted for concepts, and the course applies none of its tax rules.'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 6, 'A farm-out grants the farmor a net profit interest as part of its consideration. How does the engine value it?', '["As cash consideration, added to the carry, bonus and reimbursement", "As a carried interest, through carryRecovery of the joint venture engine", "It does not; a subordinated interest is valued outside the call", "Through backIn, with the net profit share as the target of a back-in"]'::jsonb, 2, 'The course''s list of what the engine does not compute: royalty, net profit and other subordinated interests granted as consideration (HMRC OT18320 and OT30131); the engine does nothing, and a subordinated interest is valued outside. The consideration the engine counts is carry, cash bonus and reimbursement only, and its carry and back-in functions model neither.'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 7, 'Which figure does the engine give as the market value of the 30.000000 percent Ekene working interest?', '["16000000.000000, the price the fixture states for the working interest", "7893775.278136, the risked value of the 30.000000 percent working interest", "53333333.333333, the stated price scaled up to 100 percent of the licence", "None; it reports value per percent of stated figures and ratios of stated prices"]'::jsonb, 3, 'The course''s list of what the engine does not compute: a market value for an interest comes from a transaction market; the engine computes value per percent of stated figures and ratios of stated prices. 16000000.000000 is a stated input, 7893775.278136 a value on stated terms and 53333333.333333 the stated price scaled to 100 percent, and none is asserted as market value.'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 8, 'When is a back-in triggered on the Ekene licence, according to backInRight?', '["Once the development carry is recovered, in 2036 on the compound Ekene ledger", "At a contract event the caller reports, with the target stated; the engine fixes no trigger", "When the farminee''s vested interest reaches 30.000000 percent on completion", "When the PIA s.85(4) basis is stated, from the first year of production after the refund falls due"]'::jsonb, 1, 'The course: a back-in''s trigger is a contract event the caller reports; the engine does not decide when it happens. The carry payout year, the vesting of the farm-in and the basis named for the refund are all separate facts, and none of them fires a back-in.'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 9, 'An assignment is made without consent, or a beneficial ownership notice is late. What does the engine compute for the administrative fines of AOI 2024 reg. 21?', '["The surcharge of reg. 19(9)", "Seven per cent of the value", "Nothing", "The premium of five per cent"]'::jsonb, 2, 'The course''s list of what the engine does not compute: the administrative fines for an assignment without consent or a late beneficial ownership notice, AOI 2024 reg. 21; the engine does nothing. The surcharge runs only on a late fee payment, and the seven per cent is the consent fee itself.'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 10, 'An earningObligation call lists 21 licence parties. In the engine''s words, what comes back?', '["parties must have at most 20 entries; got 21", "events must have at most 20 entries; got 21", "parties must have participatingPct summing to 100; got a sum of 90", "positions must have at most 10 entries; got 11"]'::jsonb, 0, 'DEFAULTS.MAX_PARTIES is 20, and the refusal names the cap and the count it was given: parties must have at most 20 entries; got 21. The events message answers 21 events, the sum message answers interests summing to 90, and the positions cap belongs to riskSharing.'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 11, 'A box carries an unknown key vest and lacks the vesting rule. Which refusal does the engine return first?', '["vesting must be one of \"per-event\", \"all-events\"; got nothing", "vesting must be one of \"per-event\", \"all-events\"; got \"vest\"", "Both refusals in one message, the missing vesting rule listed first and then the unknown key vest with the full list of the accepted keys", "vest is not an accepted key; the accepted keys at the top level are parties, farmor, farminee, events, vesting, eventsCompleted, cashBonus, pastCosts"]'::jsonb, 3, 'Every function checks its accepted keys before it reads a term, so the unknown key is refused first, with the path and the full list of accepted keys (the course prints this probe verbatim). A misspelt optional key is refused and never silently dropped; the engine returns one refusal at a time and never reads vest as vesting.'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 12, 'The 2033 uplift of the Ekene development carry reads 9629358.08 in the engine''s reason. Which figure should a report reason with?', '["The reason''s 9629358.08, since the reason is the engine''s own words", "The field, 9629358.080000, since a reason rounds money to the cent", "9516800.000000, the simple uplift of the same year", "12619776.000000, the 2032 uplift carried into the 2033 balance"]'::jsonb, 1, 'The convention: money in a reason is rounded to the cent, half away from zero, trailing zeros dropped, while every numeric field keeps full precision. The course therefore quotes the field, 9629358.080000, and uses a reason only verbatim. 12619776.000000 is a different year''s uplift, and 9516800.000000 is 2033 on the simple ledger, a different carry.'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 13, 'Which statement about the engine''s own code matches its declared imports?', '["It carries its own seeded Monte Carlo for riskSharing and imports the canonical npv for the success case", "It re-implements rollback for the break-even promote and imports evpi and evii for information", "It imports carryRecovery for both the farm-in split and the development carry after it", "It carries no NPV, decision tree or Monte Carlo code of its own; riskSharing alone samples, through portfolio.js"]'::jsonb, 3, 'The course: its five imports are cashflow.ts, decisionTree.js, portfolio.js, afe.js and jointVenture.js; it carries no NPV, decision tree or Monte Carlo code of its own, and the one function that samples is riskSharing, through the seeded portfolio Monte Carlo. The other parties'' shares of the farm-in come from calculatePartnerCosts of afe.js.'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 14, 'Beside its size caps and its sum tolerance, which figures does the engine hold as its own constants?', '["Only the gazetted NIGERIA_ASSIGNMENT figures, each cited to reg. 19 or PIA s.95(14)", "The Ekene deal terms of the fixture, which fill in any term a call happens to leave out", "A chance of success of 25 percent and a discount rate of 0.1 for every success case", "An uplift of 8 percent a year for any carry stated without one"]'::jsonb, 0, 'The course: every deal term is an input with no default, and a call without one is refused by name; the only figures it holds are the gazetted ones in NIGERIA_ASSIGNMENT (2 and 5 per cent, 90 and 30 days, 0.01 per cent a day for 90 days, 50 percent for a change of control). The Ekene figures are fixture terms, stated in each golden input.'),
  ('farmout', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 15, 'FIN''s EMV on the Ekene deal is -1806224.721864. What does the course say such a computed figure does not say?', '["It is no EMV of a named position, since the chance of success is stated by the caller", "It carries no weight until the survey is shot, since information may change the chance", "It is no forecast of what a partner will pay and no statement of market value", "It is no figure on fixed terms, being drawn at a seed"]'::jsonb, 2, 'The course: an EMV is what the stated chance and payoffs produce; none of the computed figures is a forecast of what a partner will pay or a statement of market value, and each is quoted with its terms. It is the EMV of FIN''s farm-in position, it is a return value on fixed terms, and nothing in dealValue is drawn.'),
  ('farmout', 'advanced', 'final', null, 1, 'EKO values the Ekene seismic survey, which costs 1500000.000000, as farmor. What is its EVII less the cost?', '["5245331.458602, and the engine says the information is worth buying", "6892331.458602, and the engine says the information is worth buying", "5392331.458602, and the engine says the information is worth buying", "-2254668.541398, and the engine says it costs more than it is worth"]'::jsonb, 2, 'info-ekene-farmor: EVII 6892331.458602, less the cost 1500000.000000, is 5392331.458602 (engine). 5245331.458602 is FIN''s net figure on the same survey; 6892331.458602 is EKO''s EVII before the cost; -2254668.541398 is FIN''s net figure at a cost of 9000000.000000.'),
  ('farmout', 'advanced', 'final', null, 2, 'EKO''s EMV with the survey is 26725365.162782. Which weighting of its best actions produces it?', '["Bright''s chance 0.375000 on 64837617.964633 and dim''s 0.625000 on 3858013.481672", "0.375000 x 17987550.556271 after bright plus 0.625000 x 0.000000 after dim, FIN''s best actions", "19833033.704181 plus the survey''s EVII of 6745331.458602 read from FIN''s side of the deal", "0.500000 x 64837617.964633 plus 0.500000 x 3858013.481672 at even signal odds for EKO"]'::jsonb, 0, 'Each signal''s best EMV for EKO (drill alone after bright, farm out after dim) weighted by the chance of that signal: 26725365.162782 (engine). The first distractor is FIN''s calculation; adding FIN''s EVII mixes two sides; even odds ignore the stated likelihoods, which give 0.375000 and 0.625000.'),
  ('farmout', 'advanced', 'final', null, 3, 'Which amplitude signal changes neither side''s action on the Ekene deal?', '["The bright signal: both sides keep the actions they took before the survey", "Neither signal: each side takes its prior action whatever the survey reads", "Both signals: each side switches action whichever way the survey comes back", "The dim signal: FIN still declines and EKO still farms out"]'::jsonb, 3, 'Without the survey FIN declines and EKO farms out. After a dim signal (posterior 10.000000 percent) FIN declines and EKO farms out, as before; after a bright one (50.000000 percent) FIN farms in and EKO drills alone (engine). So the bright signal turns both decisions and the dim one turns neither.'),
  ('farmout', 'advanced', 'final', null, 4, 'The first signal of a survey is typed with only its likelihood given success, [75]. How does the engine answer?', '["information.signals must have likelihoodsPct[0] summing to 100 over the signals (P(signal | success)); got a sum of 75", "information.signals[0].likelihoodsPct must be an array [P(signal | success), P(signal | dry hole)] in per cent; got [75]", "information.signals[0].likelihoodsPct must be a number from 0 to 100; got [75]", "information.signals must be an array of at least 2 signals; got [75]"]'::jsonb, 1, 'Each signal states two likelihoods in per cent, one given success and one given a dry hole, so the engine refuses the shape by the signal''s path, in its own words: information.signals[0].likelihoodsPct must be an array [P(signal | success), P(signal | dry hole)] in per cent; got [75]. The other three misname the rule or the field.'),
  ('farmout', 'advanced', 'final', null, 5, 'An information call lists 11 signals. What does the engine do with it?', '["Values the first 10 signals and reports the eleventh as unread in a reason", "Merges the two least likely signals so that the call fits inside the cap", "Refuses side, since the side is checked before any signal is read", "Refuses information.signals by name, citing the cap of 10 and the count of 11"]'::jsonb, 3, 'DEFAULTS.MAX_SIGNALS is 10, and the engine refuses more by name, with the cap and the count it was given (information.signals must have at most 10 entries; got 11). It truncates and merges nothing, and a stated side of farmor or farminee passes its own check.'),
  ('farmout', 'advanced', 'final', null, 6, 'Take the uninformative golden survey, where each signal is as likely under a discovery as under a dry hole. What signal chance and posterior does each signal get?', '["A chance of 0.750000 and a chance of success after it of 50.000000 percent", "A chance of 0.500000 and a chance of success after it of 50.000000 percent", "A chance of 0.500000 and a chance of success after it of 25.000000 percent", "A chance of 0.375000 and a chance of success after it of 10.000000 percent"]'::jsonb, 2, 'Equal likelihoods under both outcomes make each signal equally likely, 0.500000, and leave the chance of success where it was, 25.000000 percent (engine). A signal that moves nothing turns no decision, and EVII is 0.000000. 0.375000 and 10.000000 belong to the Ekene survey''s two signals.'),
  ('farmout', 'advanced', 'final', null, 7, 'FIN''s EVII on the Ekene survey, 6745331.458602, sits below its EVPI of 14393775.278136. Why?', '["The survey is imperfect: bright still leaves a dry-hole chance of 50.000000 percent, and dim hides a 10.000000 percent chance of success", "The survey''s stated cost of 1500000.000000 is taken off EVII before the engine compares it with EVPI, so the gap is the cost", "EVPI is computed at the posterior chance after each signal and EVII at the prior chance of 25.000000 percent", "EVII is a Monte Carlo estimate drawn over the two signals, while EVPI is the exact closed-form ceiling above it"]'::jsonb, 0, 'EVPI assumes the outcome is known; the survey only shifts the chance of success, to 50.000000 after bright and 10.000000 after dim, so FIN still farms in on some dry holes and walks away from some successes. EVII is before the cost (the net figure is 5245331.458602), and informationValue draws nothing.'),
  ('farmout', 'advanced', 'final', null, 8, 'On risk-ekene (seed 20271111, 20000 draws) the farm-out lifts EKO''s P90. Which drawn figure moves the other way for EKO?', '["Its EMV, which falls from 19833033.704181 alone to 18418808.982316 after", "Its high case, estimated at 157675235.929265 alone and 99708134.816723 after", "Its standard deviation, which rises from 46115911.128875 to 80399735.584206", "Its chance of a loss, estimated at 0.747650 alone and 0.752450 after the deal"]'::jsonb, 1, 'The draws put EKO''s high case at 157675235.929265 alone and 99708134.816723 after the farm-out (engine, seed 20271111, 20000 draws). The EMV rises (18418808.982316 to 19833033.704181), the standard deviation falls, and the two loss-chance estimates in the distractor are swapped.'),
  ('farmout', 'advanced', 'final', null, 9, 'On risk-spread-four, four independent prospects at 25 percent each, why does the low case stay at -40000000.000000 while the spread halves?', '["The engine takes the low case from the dry-hole payoff in closed form, with no draws", "Spreading the bet lowers only the high case, and the low case is fixed at the fail cost", "The chance that all four wells fail together is still above 10 percent", "The correlation of 0.500000 keeps the four wells failing together at the P90"]'::jsonb, 2, 'The ninetieth percentile of exceedance still falls where every well fails: with a dry-hole chance of 0.750000 for each of four independent wells, all four fail together far more often than 10 percent of the time. The low case is a drawn percentile, the call states a correlation of 0.000000 (0.500000 is risk-correlated), and nothing fixes a low case in advance.'),
  ('farmout', 'advanced', 'final', null, 10, 'On risk-psu, seed 7 and 50000 draws, the engine prints a chance of a loss of 0.651800 for drilling yourself, where the Penn State page states a dry-hole chance of 65.000000 percent. How should the two be read?', '["0.651800 is the exact chance of a loss, and the page''s chance is a rounded version of it", "The two disagree, so the engine''s reading of the page''s chances must be at fault somewhere", "0.651800 is the page''s figure less the chance that the farm out position also loses money", "A sample of 50000 seeded draws landing near the 65.000000 percent the page states"]'::jsonb, 3, 'Drilling yourself loses on every dry hole and on nothing else, so the draws estimate the dry-hole chance the page states, 65.000000 percent, as 0.651800. The farm out never loses (its chance of a loss is 0.000000), and a draw is an estimate, so no disagreement follows.'),
  ('farmout', 'advanced', 'final', null, 11, 'risk-spread-four prints a chance of a loss of 0.341480 for four independent prospects (50000 draws, seed 11) and risk-correlated prints 0.480300 for four correlated ones (20000 draws, seed 11). What must a reader check before comparing them?', '["The draw counts, which differ, so the two estimates carry different sampling error", "The EMVs, which differ, so the two chances of a loss rest on different values of the bet", "The seeds, which differ, so the two calls draw from unrelated streams of random numbers", "Nothing: estimates at the same seed compare directly whatever the draw count"]'::jsonb, 0, 'Read the draw counts before comparing estimates: the two rows state 50000 and 20000 draws. Both EMVs are 20000000.000000 and both seeds are 11. The standard deviations are closed form and compare directly.'),
  ('farmout', 'advanced', 'final', null, 12, 'A riskSharing call asks for 200001 draws. What does the engine do?', '["Draws 200000 and reports the cap in a reason beside the estimates", "Refuses iterations, naming 200000 as the most draws one call accepts", "Refuses iterations, naming 166666 as the most three holdings allow", "Refuses seed, since the draw count is read only after the seed"]'::jsonb, 1, 'DEFAULTS.MAX_ITERATIONS is 200000, and a count above it is refused by name before the draw-work rule is read (iterations must be an integer from 1 to 200000 (stated; no default); got 200001). The engine caps nothing silently; 166666 is the draw-work limit for three holdings, a different rule; a stated seed passes its own check.'),
  ('farmout', 'advanced', 'final', null, 13, 'A holding in a risk call states a fail cost of -1. What comes back?', '["positions[0].holdings[0].successStdDev must be a finite number at or above 0; got nothing", "positions[0].holdings[0].failCost must be a finite number at or above 0; got -1", "A result that reads -1 as a gain of 1 on failure, the sign reversed", "positions[0].holdings[0].failCost must be a finite number below 0; got -1"]'::jsonb, 1, 'A fail cost is a cost, stated at or above 0, and the engine refuses a negative one in its own words: positions[0].holdings[0].failCost must be a finite number at or above 0; got -1. The successStdDev message answers a missing standard deviation.'),
  ('farmout', 'advanced', 'final', null, 14, 'On risk-ekene, which holdings make up EKO''s position after the farm-out?', '["Ekene Deep 70% at 25.000000 percent (success 157675235.929265, fail cost 28000000.000000) less the cash it receives", "Ekene Deep 40% at 25.000000 percent (success 99708134.816723, fail cost 6792000.000000) alone, with no cash holding", "Ekene Deep 30% at 25.000000 percent and the whole consideration of 10000000.000000 held as cash at 100", "Ekene Deep 40% at 25.000000 percent (success 94500134.816723, fail cost 12000000.000000) and cash of 5208000.000000 at 100"]'::jsonb, 3, 'The golden input: Ekene Deep 40% with success value 94500134.816723 and fail cost 12000000.000000, plus the certain cash 5208000.000000 at a chance of 100 and standard deviation 0. The 70% holding is the drill-alone position; 99708134.816723 and -6792000.000000 are the deal view''s payoffs, which already include the cash.'),
  ('farmout', 'advanced', 'final', null, 15, 'How does the engine reach the Ekene Deep 100 percent risked EMV of 26312584.260452?', '["25.000000 percent of 271250337.041807 less the dry-hole cost of 40000000.000000", "25.000000 percent of 225250337.041807, the dry hole weighed at 0.000000", "25.000000 percent of 225250337.041807 plus 75 percent of -40000000.000000", "The mean of 225250337.041807 and -40000000.000000 at even chances"]'::jsonb, 2, 'The rule: the risked figure is the EMV of the 100% position, rolled back at the stated chance: success 225250337.041807, dry hole -40000000.000000, at 25.000000 percent (engine). The other paths drop the success well cost, drop the dry hole or ignore the stated chance.'),
  ('farmout', 'advanced', 'final', null, 16, 'Scaled from 30.000000 percent to the whole licence, what does the stated Ekene price of 16000000.000000 come to in the engine''s price view?', '["53333333.333333", "16000000.000000", "26312584.260452", "48000000.000000"]'::jsonb, 0, 'The price per percent is 533333.333333, and scaled to the whole licence it is 53333333.333333 (engine), a ratio of stated inputs reported only. 16000000.000000 is the stated price, 26312584.260452 the computed 100 percent risked EMV, and 48000000.000000 appears in no price output.'),
  ('farmout', 'advanced', 'final', null, 17, 'A prospect whose risked EMV at 100 percent is -30000000.000000 (interest-negative-emv) is priced per percent. What success-case figure sits beside the negative risked one?', '["None, since the engine prints no success-case figure when the risked one is at or below 0", "-300000.000000 a percent, since the two bases share one EMV rollback", "40000.000000 a percent, the stated price per percent on that basis", "1600000.000000 a percent, reported beside the risked figure on every call"]'::jsonb, 3, 'Both per-percent figures are computed on every call: risked -300000.000000 and success case 1600000.000000 (engine). The success case is the success-case value less the success well cost, over 100, with no chance weighting. 40000.000000 is the stated price per percent, and the missing figure on this call is the price-to-value ratio alone.'),
  ('farmout', 'advanced', 'final', null, 18, 'interest-production-metric states a price of 18000000.000000 for 20.000000 percent with 1000.000000 boe/d net to the working interest. What price per flowing unit and ratio does the engine print?', '["18000.000000 per boe/d, and 1.125000 times the success-case value per percent", "800000.000000 per boe/d, the value per percent over the stated rate of flow", "18000.000000 per boe/d, and 2.026914 times the risked value per percent of the field", "900000.000000 per boe/d, the price per percent over the stated rate net to the interest"]'::jsonb, 0, 'The engine divides the price by the rate net to the working interest: 18000000.000000 over 1000.000000 is 18000.000000, and 900000.000000 a percent over 800000.000000 is 1.125000 (engine). 2.026914 is the Ekene risked ratio; 900000.000000 is the price per percent and 800000.000000 the value per percent on either basis, neither of them per flowing unit.'),
  ('farmout', 'advanced', 'final', null, 19, 'A price call states reserves with a category and volume but leaves the volume unit out. Which message does the engine give?', '["transaction.volumeUnit must be left out when no reserves are stated; got \"boe\"", "transaction.reserves must have at most 10 entries; got 11", "transaction.volumeUnit must be a non-empty string; got nothing", "interestPct must be a number above 0 and at most 100; got 0"]'::jsonb, 2, 'Here the category and volume arrive and the unit is missing, and the engine names the unit field: transaction.volumeUnit must be a non-empty string; got nothing. The reverse case gets its own left-out message; eleven reserve categories break the cap of 10; and the interestPct message answers a working interest of 0.'),
  ('farmout', 'advanced', 'final', null, 20, 'The same Ekene price reads 2.026914 on the risked basis and 0.236774 on the success-case basis. What follows for a report?', '["It quotes the risked ratio, since the success-case figure assumes the risk away", "It names the basis with the ratio, since a reader not told it cannot tell which is meant", "It quotes the average of the two ratios as a single figure for the price of the working interest", "It quotes the lower ratio, the safer figure for a buyer to rely on"]'::jsonb, 1, 'The course: a reader who is not told the basis cannot tell which one they are reading, and a report that quotes a value per percent or a ratio names its basis every time. The engine prints both per-percent figures; neither is the correct one in general, and the average is no engine figure.'),
  ('farmout', 'advanced', 'final', null, 21, 'HMRC''s manual says "The consideration for the disposal of an interest in a producing field is generally in the form of cash or shares" (HMRC Oil Taxation Manual OT30023). What does the engine do with a consideration paid in shares?', '["Counts the shares at their stated price in the value of the transaction", "It prices the shares per percent of working interest on the risked basis", "It treats the shares as cash consideration, as OT30081 does for a reimbursement", "Nothing: it values no shares, so a ratio would need their value from outside"]'::jsonb, 3, 'The course: a consideration in shares, or in a royalty or net profit interest, would need its own value before any ratio could be taken, and the engine values none of those. OT30081 treats a reimbursement of earlier costs as cash consideration, which says nothing about shares.'),
  ('farmout', 'advanced', 'final', null, 22, 'In 2033 the compound Ekene ledger opens at 120366976.000000. At 8.000000 percent a year, what is added before any recovery?', '["9516800.000000, the simple ledger''s figure for the same year", "9629358.080000, which the reason prints to the cent as 9629358.08", "12619776.000000, the figure charged on the 2032 opening balance", "129996334.080000, the balance due once the year''s addition is in"]'::jsonb, 1, '8 percent of 120366976.000000 is 9629358.080000 (engine), and the course reasons with that field. 9516800.000000 is the simple ledger''s 2033 line on its own principal; 12619776.000000 belongs to 2032; 129996334.080000 is the 2033 balance due, opening plus uplift.'),
  ('farmout', 'advanced', 'final', null, 23, 'Over the life of the compound Ekene development carry, what does the engine recover in all?', '["190353141.996585: the carried cost 144000000.000000 plus uplift 46353141.996585", "144000000.000000 plus the simple uplift of 44438966.681600, recovered by 2036", "144000000.000000: the carried cost alone, the uplift written off in 2036", "100000000.000000: the recovery up to the stated cap, 44000000.000000 written off"]'::jsonb, 0, 'devcarry-ekene recovers 190353141.996585 by 2036, with nothing written off (engine). The simple uplift of 44438966.681600 belongs to the other ledger; 100000000.000000 with 44000000.000000 written off is devcarry-ekene-none-capped, a different stated carry with no uplift and a cap.'),
  ('farmout', 'advanced', 'final', null, 24, 'The Ekene simple carry is restated with dayBasis "actual/365" (a stated probe). What uplift does the engine add in 2032, and why does it differ from 11520000.000000?', '["11520000.000000, since actual/365 and annual-period agree in every year", "11551561.643836, since actual/365 compounds the accrued simple interest", "11551561.643836, since 2032 has 366 days counted over 365", "12619776.000000, since actual/365 charges the uplift on the whole opening balance of the year"]'::jsonb, 2, 'Under actual/365 each ledger year counts its calendar days over 365; 2032 has 366, so the uplift on the principal of 144000000.000000 is 11551561.643836 against 11520000.000000 under annual-period (engine). The day basis compounds nothing; 12619776.000000 is the compound ledger''s 2032 uplift, a different carry.'),
  ('farmout', 'advanced', 'final', null, 25, 'On backin-ekene EKO backs in from 40.000000 to 45.000000 percent. What refund does PA receive, and why that amount?', '["12000000.000000, in proportion to the 2.500000 points it cedes", "24000000.000000, the whole refund, since PA is the larger other party", "144000000.000000, the refund PA pays when it backs in to 60.000000 percent under the PIA basis", "0.000000, since a back-in refund is paid to the Government alone"]'::jsonb, 0, 'The refund of 24000000.000000 is received in proportion to the interest given up; PA and FIN each cede 2.500000 points, so each receives 12000000.000000 (engine). 144000000.000000 is the refund PA itself pays on backin-ekene-pia, a different back-in; the refund goes only to the parties that cede, and the contract basis names no Government.'),
  ('farmout', 'advanced', 'final', null, 26, 'On backin-ekene-pia the refund of 144000000.000000 is recovered from future entitlement. In which year is it recovered, and what is carried into that year?', '["2033, with the whole 144000000.000000 recovered from the year''s available share", "2036, as on the Ekene development carry, whose ledger the back-in joins", "2034, with 120000000.000000 carried after 24000000.000000 is recovered in 2033", "2034, with 24000000.000000 carried after 120000000.000000 is recovered in 2033"]'::jsonb, 3, 'The reasons: 2033: 120000000 recovered of 144000000 due; 24000000 carried to 2034; and in 2034 the balance 24000000 is recovered (engine). The back-in keeps its own ledger, separate from the development carry, and the available share of 120000000.000000 caps 2033.'),
  ('farmout', 'advanced', 'final', null, 27, 'On devcarry-ekene, with a discount rate of 0.100000 to 2027, what NPV does the engine return for EKO?', '["81375101.112542", "115507461.937032", "74367773.992233", "271250337.041807"]'::jsonb, 1, 'The development carry ledger feeds each party''s cash flow, and at 0.100000 to 2027 the engine returns EKO 115507461.937032, PA 81375101.112542 and FIN 74367773.992233 (engine). 271250337.041807 is the success-case value at 100 percent in the deal view.'),
  ('farmout', 'advanced', 'final', null, 28, 'A back-in is stated for NOC, a party that holds no participating interest in the Ekene licence after the farm-in. How does backInRight answer?', '["backIn.targetPct must be above the back-in party''s current interest 0; got 45", "A back-in in which NOC takes its target from the three parties in proportion", "backIn.party must be one of \"EKO\", \"PA\", \"FIN\"; got \"NOC\"", "farminee.id must be an id no licence party has (EKO, PA); got \"NOC\""]'::jsonb, 2, 'The back-in party must be one of the parties after the farm-in, and the engine names them in its own words: backIn.party must be one of "EKO", "PA", "FIN"; got "NOC". It computes no back-in for an outsider; the target check applies only to a named party, and the farminee.id message belongs to earningObligation.'),
  ('farmout', 'advanced', 'final', null, 29, 'On fee-day-121 the payment comes 121 days after the notification. What does the engine charge?', '["No surcharge, since day 121 is the last day of the further 30 days", "1 surcharge day, 39.200000, a total paid of 392039.200000", "31 surcharge days, counted from the end of the first 90 days", "1 surcharge day, 39.200000 on top of the value of the transaction"]'::jsonb, 1, 'Day 121 is the first day after the 90 + 30 days: 0.01% of 392000 x 1 day = 39.2, a total paid of 392039.200000 (engine). Day 120 is the last grace day; the surcharge runs only after the grace and is charged on the fee alone.'),
  ('farmout', 'advanced', 'final', null, 30, 'On fee-day-211, what does consentFee return?', '["A result: status consent-deemed-withdrawn and no total paid", "A refusal naming payment.paidOn, since the date is past day 210", "A result: 91 surcharge days at 39.200000 each, added to the fee", "A refusal naming basis, since a withdrawn consent leaves nothing to charge"]'::jsonb, 0, 'The reason: paid 211 days after the notification: more than 90 surcharge days after the 90 + 30 days; the consent is deemed withdrawn (reg. 19(9)). A consent deemed withdrawn is a result returned with a reason; no field is refused, and the surcharge stops at 90 days.'),
  ('farmout', 'advanced', 'final', null, 31, 'Reg. 19(6) says consent is not granted until the application and processing fees are paid in full, while reg. 19(7) gives 90 days from the notification of the grant. How does the engine handle the two?', '["It charges the processing fee before consent and the premium within 90 days of the grant, splitting the seven per cent", "It refuses any payment date, since the two provisions cannot both apply to the same fee", "It applies reg. 19(6) alone and treats any payment after the consent as a withdrawal of it", "It applies the timing of reg. 19(7) to (9) to the whole seven per cent and computes no application fee"]'::jsonb, 3, 'The course: the engine applies the timing of reg. 19(7) to (9) to the whole seven per cent and computes no application fee (reg. 19(1) leaves it to other regulations). The texts print both provisions, and the course shows the quirk as they print it.'),
  ('farmout', 'advanced', 'final', null, 32, 'HMRC''s manual separates a farm in, assigned before the work, from an earn-in, where the work is completed before the assignment (OT30021). Which engine terms answer those two orders?', '["The overrun rules post-deal-interests and farmor-side", "The value bases risked and success-case", "The vesting rules per-event and all-events", "The uplift types simple and compound"]'::jsonb, 2, 'The engine''s two vesting rules are those two orders: each completed event vests its stated interest (a farm in: assignment with the work, HMRC OT30021), and nothing vests until every event is completed (an earn in: the work before the assignment, HMRC OT30021). The overrun rules, value bases and uplift types answer other questions.'),
  ('farmout', 'advanced', 'final', null, 33, 'Run as a deal on deal-psu-eme801, the Penn State problem gives the incoming party a break-even share and a break-even chance. Which does the page itself print?', '["Both, 98.000000 and 35.714286, beside its EMVs of 12500.000000 and 17500.000000", "The break-even chance alone, 35.000000 percent, the producer chance it states", "The break-even share alone, 93.333333 percent, the interest it assigns", "Neither; the engine finds 98.000000 percent of the well and 35.714286 percent"]'::jsonb, 3, 'The page prints its payoffs, chances and the EMVs 12500.000000 and 17500.000000; the engine finds the incoming party breaks even paying 98.000000 percent of the well for 93.333333 percent and at a chance of 35.714286 percent, and the page prints neither figure. 93.333333 is the golden input''s earned share, since the page states no interest.'),
  ('farmout', 'advanced', 'final', null, 34, 'On earn-cap-gross-exactly the gross cost of 40000000.000000 equals the gross-cost cap. What does the engine return?', '["Cap state exceeded, since a cost at the cap is treated as over it", "Cap state exactly, excess 0.000000, the promote on all of the cost", "Cap state below, with the overrun rule applied to 0.000000 of excess", "A refusal of cap.amount, since a cap must lie above the gross cost"]'::jsonb, 1, 'The boundary table: a gross cost equal to the cap is its own state, exactly, with excess 0.000000 and the promote on all of it, splitting the cost as a cap not reached would. Each rule has its own boundary, and the engine refuses no cap equal to the cost.'),
  ('farmout', 'advanced', 'final', null, 35, 'Where in the Petroleum Industry Act 2021 does the definition of a farm-out sit, and what does the engine take from that?', '["In s.94(8), the marginal field section; the engine''s arithmetic applies to any farm-out a caller states", "In s.95(14), the change of control provision; the engine applies it only above 50 percent", "In s.233(10), the decommissioning provision; the engine applies it to every farm-out", "In s.94(8), the marginal field section; the engine refuses a farm-out outside a marginal field"]'::jsonb, 0, 'Section 94(8) opens "For the purpose of this section", and s.94 is the marginal field section; the Act uses the word again in s.233(10) and the tax sections without a second definition. The engine''s arithmetic applies to any farm-out a caller states, and it refuses nothing by field type.'),
  ('farmout', 'advanced', 'final', null, 36, 'A PEL assignment is priced on fee-pel-stated under basis stated, with 1.500000 percent processing and 0.000000 percent premium on 1000000.000000. What does the engine return?', '["A fee of 15000.000000 at the stated rates, which are no gazetted figure", "A refusal, since a PEL is refused under every fee basis the engine accepts, stated or gazetted", "A fee at the gazetted seven per cent on 1000000.000000, the stated rates set aside", "A fee at the intra group two per cent on the same 1000000.000000 value of the transaction"]'::jsonb, 0, 'Reg. 19(2) sets the fee for the Minister''s consent, and a PEL''s consent is the Commission''s, so the engine refuses a PEL under basis nuprc-2024-r19 and prices it under basis stated at the rates the caller gives: 15000.000000 (engine). The Commission''s own PEL fee is not computed.'),
  ('farmout', 'advanced', 'final', null, 37, 'A risk call puts 51 holdings in one position. Which message does the engine return?', '["positions must have at most 10 entries; got 51", "iterations must be at most 166666 for 51 holdings in all; got 20000", "positions[0].holdings must have at most 50 entries; got 51", "A result that draws the first 50 holdings and reports the rest"]'::jsonb, 2, 'DEFAULTS.MAX_HOLDINGS is 50 in one position, and the engine names the cap and the count: positions[0].holdings must have at most 50 entries; got 51. It drops no holding; the positions cap is 10 positions, and the draw-work message is invented for this call.'),
  ('farmout', 'advanced', 'final', null, 38, 'A call to earningObligation carries the key carryCap, which the function does not read. What does the engine do with it?', '["Reads it as the cap of the first event, since the name of the key says what it means", "Ignores it and returns the obligation without a cap on any event of the call", "Refuses the first event''s cap, since a cap may be stated only once in one call", "Refuses it: carryCap is not an accepted key, with the accepted keys at the top level listed"]'::jsonb, 3, 'The engine''s words: carryCap is not an accepted key; the accepted keys at the top level are parties, farmor, farminee, events, vesting, eventsCompleted, cashBonus, pastCosts. A key a function does not read is refused at whatever level it sits; it never silently drops a term or guesses at one.'),
  ('farmout', 'advanced', 'final', null, 39, 'The farm-out report names every figure with its terms. What does it name about the readings?', '["Only the readings that the law prescribes", "Each reading the figures rest on", "None, since no graded figure rests on one", "The reading of the reader''s own choosing"]'::jsonb, 1, 'The report''s list ends with each reading the figures rest on, and a report quoting a figure names the reading it rests on. No reading is prescribed by the texts: each is the engine''s stated choice where a text leaves one open. That no capstone field depends on one does not excuse a report.'),
  ('farmout', 'advanced', 'final', null, 40, 'At the break-even promote exactly (deal-promote-exactly-break-even), FIN''s EMV is 0.000000. What does the engine report about the farminee''s best action?', '["Decline, since an EMV of 0 is no gain to FIN", "Farm in, since an EMV of 0 is no loss to FIN", "A tie, with farm in and decline both named", "A refusal of the share asked, 50 percent of it"]'::jsonb, 2, 'The convention: ties are reported, every tied action named (engines/economics/decisionTree.js). At the break-even share the engine reports a tie between farm in and decline, and the farmor''s two actions tie as well. It breaks no tie and refuses nothing.'),
  ('farmout', 'advanced', 'final', null, 41, 'The Ekene well costs 46000000.000000 on a success. What does the engine compute for that cost discounted to the date it is spent?', '["Nothing: every cost sits at the valuation date, undiscounted", "A present value at 0.100000 to 2027, by the canonical npv", "Discounted at the rate of the success-case cash flows", "Its present value at a rate the call states for the well costs alone"]'::jsonb, 0, 'The list of what is not computed includes well costs discounted to their own dates; in their place the engine puts every cost at the valuation date, undiscounted, the reading it states. The call has no rate for costs, and the canonical npv values only the success-case cash flows.'),
  ('farmout', 'advanced', 'final', null, 42, 'What does every graded number of this course have in common?', '["Each is quoted in the lessons beside its own capstone", "Each is a return value of the engine on fixed inputs", "Each is a seeded draw that repeats the same on any machine", "Each rests on one of the four stated readings"]'::jsonb, 1, 'The course: every graded number is a return value of this engine on fixed inputs; the capstones run their own synthetic deals, which the lessons never print; no graded figure is a Monte Carlo draw; and none depends on a reading.');
